// Validate the form before anything is sent to Meta or saved.
const f = $json;
const c = {
  name: String(f['Client name'] ?? '').trim().slice(0, 100),
  id: String(f['Client id'] ?? '').trim().toLowerCase(),
  fb_page_id: String(f['Facebook Page id'] ?? '').trim(),
  timezone: String(f['Timezone'] ?? '').trim() || 'Asia/Dubai',
  report_email: String(f['Report email'] ?? '').trim(),
  token: String(f['Page access token'] ?? '').trim(),
};
const problems = [];
if (!c.name) problems.push('Client name is empty.');
if (!/^[a-z0-9][a-z0-9-]{1,40}$/.test(c.id)) problems.push('Client id: lowercase letters, numbers and dashes only.');
if (!/^\d{5,25}$/.test(c.fb_page_id)) problems.push('Facebook Page id must be digits only.');
try { new Intl.DateTimeFormat('en', { timeZone: c.timezone }); } catch { problems.push(`Unknown timezone "${c.timezone}".`); }
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.report_email)) problems.push('Report email is not valid.');
if (c.token.length < 50) problems.push('The Page access token looks too short.');
return { ...c, ok: problems.length === 0, problem: problems.join(' ') };

