// Same rules Meta applies, so an accepted post will publish.
const f = $json;
const p = {
  client_id: String(f['Client id'] ?? '').trim().toLowerCase(),
  id: String(f['Post id'] ?? '').trim().toLowerCase(),
  type: f['Type'],
  media_url: String(f['Media URL'] ?? '').trim(),
  caption: String(f['Caption'] ?? '').trim(),
  hashtags: String(f['Hashtags'] ?? '').split(/[\s,]+/).map((t) => t.replace(/^#/, '')).filter(Boolean),
  link: String(f['Link'] ?? '').trim(),
  link_on_instagram: f['Link on Instagram'] === 'Yes',
  platforms: [].concat(f['Platforms'] ?? []),
  publish_at: String(f['Publish at'] ?? '').trim(),
};
const problems = [];
const isUrl = (u) => { try { return new URL(u).protocol === 'https:'; } catch { return false; } };
if (!/^[a-z0-9][a-z0-9-]{1,40}$/.test(p.client_id)) problems.push('Client id is not valid.');
if (!/^[a-z0-9][a-z0-9-]{2,80}$/.test(p.id)) problems.push('Post id: lowercase letters, numbers and dashes, 3 to 81 characters.');
if (!['image', 'reel'].includes(p.type)) problems.push('Type must be image or reel.');
if (!isUrl(p.media_url)) problems.push('Media URL must be a public https address.');
const ext = (p.media_url.split('?')[0].match(/\.([a-z0-9]+)$/i)?.[1] ?? '').toLowerCase();
if (p.type === 'reel' && ext !== 'mp4') problems.push('A reel must be an .mp4 file.');
if (p.type === 'image' && !['jpg', 'jpeg', 'png'].includes(ext)) problems.push('An image must be .jpg or .png.');
if (p.type === 'image' && ext === 'png' && p.platforms.includes('instagram')) problems.push('Instagram does not accept PNG; use .jpg.');
if (!p.caption || p.caption.length > 2000) problems.push('Caption must be 1 to 2000 characters.');
if (p.hashtags.length > 30) problems.push('Instagram allows at most 30 hashtags.');
if (p.link && !isUrl(p.link)) problems.push('Link must be an https address.');
if (!p.platforms.length) problems.push('Pick at least one platform.');
const at = new Date(p.publish_at);
if (!/(Z|[+-]\d\d:\d\d)$/.test(p.publish_at) || isNaN(at)) problems.push('Publish at needs a date, time and timezone, for example 2026-12-01T19:00:00+04:00.');
else if (at < Date.now() - 5 * 60 * 1000) problems.push('Publish at is in the past.');
return { ...p, publish_at: isNaN(at) ? null : at.toISOString(), ok: problems.length === 0, problem: problems.join(' ') };

// Caption per platform: Facebook gets the link with UTM tags; Instagram only if asked (links there aren't clickable).
const withUtm = (link, source, campaign) => {
  try {
    const u = new URL(link);
    if (!u.searchParams.has('utm_source')) u.searchParams.set('utm_source', source);
    if (!u.searchParams.has('utm_medium')) u.searchParams.set('utm_medium', 'post');
    if (!u.searchParams.has('utm_campaign')) u.searchParams.set('utm_campaign', campaign);
    return u.toString();
  } catch { return link; }
};
return $input.all().map(({ json: p }) => {
  const parts = [p.caption.trim()];
  if (p.link && (p.platform === 'facebook' || p.link_on_instagram)) parts.push(withUtm(p.link, p.platform, p.id));
  const tags = (p.hashtags ?? []).map((t) => `#${t}`);
  if (tags.length) parts.push(tags.join(' '));
  const step = p.platform === 'facebook' ? 'facebook'
    : p.target_status === 'pending' || !p.container_id ? 'ig_create' : 'ig_check';
  return { json: { ...p, final_caption: parts.join('\n\n'), step } };
});

