// Turn any error (Meta API error or failed Instagram container) into one message, and decide whether to give up.
const p = $('Prepare posts').item.json;
const raw = JSON.stringify($json);
let message;
if ($json.status_code) message = `Instagram could not process the media (${$json.status_code}${$json.status ? ': ' + $json.status : ''}). Usually the file format; check the media rules.`;
else message = [$json.error?.description, $json.error?.message].filter(Boolean).join(' | ') || raw;
const code = Number(raw.match(/code\\?"\s*:\s*(\d+)/)?.[1]);
const auth_problem = [190, 10, 200, 102].includes(code) || !p.token;
const attempts = p.attempts + 1;
return {
  post_id: p.id, platform: p.platform, client_name: p.client_name, report_email: p.report_email,
  scheduled_at: p.scheduled_at, timezone: p.timezone,
  message: (p.token ? message : 'No Meta token saved for this client.').slice(0, 500),
  attempts, auth_problem, give_up: attempts >= 3 || auth_problem,
};

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const when = (iso, tz) => new Date(iso).toLocaleString('en-GB', { timeZone: tz, weekday: 'short', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const layout = (title, body) => `<div style="font-family:system-ui,sans-serif;max-width:640px;margin:auto;color:#1f2933"><h2 style="margin-bottom:4px">${esc(title)}</h2>${body}<p style="color:#9aa5b1;font-size:12px;margin-top:24px">Sent by your social publishing automation.</p></div>`;
const table = (head, rows) => `<table style="border-collapse:collapse;width:100%;font-size:14px"><tr>${head.map((h) => `<th style="text-align:left;border-bottom:2px solid #e4e7eb;padding:6px">${esc(h)}</th>`).join('')}</tr>${rows.map((r) => `<tr>${r.map((c) => `<td style="border-bottom:1px solid #e4e7eb;padding:6px;vertical-align:top">${c}</td>`).join('')}</tr>`).join('')}</table>`;
const f = $('Describe failure').item.json;
const html = layout('A scheduled post failed', `
<p><b>${esc(f.post_id)}</b> could not be published to <b>${esc(f.platform)}</b> after ${f.attempts} attempt(s).</p>
<p style="background:#fff4f4;border-left:3px solid #e12d39;padding:8px 12px">${esc(f.message)}</p>
<p>It was scheduled for ${esc(when(f.scheduled_at, f.timezone))}. Other platforms are not affected.</p>
${f.auth_problem ? '<p>This is an access problem: the Page token expired or lost a permission. Reconnect the Page with the <b>Add a client</b> form, then the post can be retried.</p>' : ''}`);
return { to: f.report_email, subject: `Post failed on ${f.platform}: ${f.post_id}`, html };

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const when = (iso, tz) => new Date(iso).toLocaleString('en-GB', { timeZone: tz, weekday: 'short', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const layout = (title, body) => `<div style="font-family:system-ui,sans-serif;max-width:640px;margin:auto;color:#1f2933"><h2 style="margin-bottom:4px">${esc(title)}</h2>${body}<p style="color:#9aa5b1;font-size:12px;margin-top:24px">Sent by your social publishing automation.</p></div>`;
const table = (head, rows) => `<table style="border-collapse:collapse;width:100%;font-size:14px"><tr>${head.map((h) => `<th style="text-align:left;border-bottom:2px solid #e4e7eb;padding:6px">${esc(h)}</th>`).join('')}</tr>${rows.map((r) => `<tr>${r.map((c) => `<td style="border-bottom:1px solid #e4e7eb;padding:6px;vertical-align:top">${c}</td>`).join('')}</tr>`).join('')}</table>`;
const c = $json;
const rows = c.posts.map((p) => [
  `<b>${esc(when(p.at, c.timezone))}</b><br><span style="color:#7b8794">${esc(p.type)} · ${esc(p.platforms)}</span>`,
  `<div style="white-space:pre-line">${esc(p.caption.length > 280 ? p.caption.slice(0, 280) + '...' : p.caption)}</div>
   ${p.hashtags.length ? `<div style="color:#2563eb;margin-top:4px">${esc(p.hashtags.map((t) => '#' + t).join(' '))}</div>` : ''}
   <div style="font-size:12px;margin-top:6px"><a href="${esc(p.media_url)}">View media</a> · id <code>${esc(p.id)}</code></div>`,
]);
const n = c.posts.length;
return {
  to: c.report_email,
  subject: `${c.name}: ${n} post${n === 1 ? '' : 's'} going out in the next 24 hours`,
  html: layout(`Next 24 hours: ${n} post${n === 1 ? '' : 's'}`, `<p>These posts will be published for <b>${esc(c.name)}</b>. Reply to this email to hold one back.</p>${table(['When', 'Post'], rows)}`),
};

// Facebook and Instagram name things differently; store one set of numbers per post.
const t = $('Posts to refresh').item.json;
const d = $json;
if (d.error) return { ...t, error: String(d.error.description || d.error.message || 'Meta refused').slice(0, 500), raw: {} };
const raw = {};
for (const m of [...(d.data ?? []), ...(d.insights?.data ?? []), ...(d.video_insights?.data ?? [])]) {
  raw[m.name] = Number(m.values?.[0]?.value ?? m.total_value?.value ?? 0);
}
if (d.reactions) raw.reactions = d.reactions.summary?.total_count ?? 0;
if (d.likes) raw.reactions = d.likes.summary?.total_count ?? 0;
if (d.comments) raw.comments = d.comments.summary?.total_count ?? 0;
if (d.shares) raw.shares = d.shares.count ?? 0;
const m = t.platform === 'instagram'
  ? { reach: raw.reach, views: raw.views, likes: raw.likes, comments: raw.comments, shares: raw.shares, saves: raw.saved }
  : { reach: raw.post_total_media_view_unique, views: raw.post_media_view ?? raw.blue_reels_play_count, likes: raw.reactions, comments: raw.comments, shares: raw.shares };
return { ...t, ...m, raw, error: null };

// Everything the report shows, minus the token. Also the prompt for the written analysis.
const c = $('Clients & week stats').item.json;
const followers = $json.error ? { facebook: null, instagram: null }
  : { facebook: $json.followers_count ?? $json.fan_count ?? null, instagram: $json.instagram_business_account?.followers_count ?? null };
const data = { client: c.name, week_start: c.week_start, week_end: c.week_end, followers, prev_followers: c.prev_followers, posts: c.posts, failed: c.failed };
const prompt = `You are a social media analyst. Write the analysis section of this week's report for a small business, from the JSON below.
3 to 5 short sentences, plain text, no headings, no bullet points, no markdown. Say what worked best and one concrete thing to try next week.
If there were no posts, say so in one sentence.

${JSON.stringify(data)}`;
return { client_id: c.id, report_email: c.report_email, data, prompt };

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const when = (iso, tz) => new Date(iso).toLocaleString('en-GB', { timeZone: tz, weekday: 'short', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const layout = (title, body) => `<div style="font-family:system-ui,sans-serif;max-width:640px;margin:auto;color:#1f2933"><h2 style="margin-bottom:4px">${esc(title)}</h2>${body}<p style="color:#9aa5b1;font-size:12px;margin-top:24px">Sent by your social publishing automation.</p></div>`;
const table = (head, rows) => `<table style="border-collapse:collapse;width:100%;font-size:14px"><tr>${head.map((h) => `<th style="text-align:left;border-bottom:2px solid #e4e7eb;padding:6px">${esc(h)}</th>`).join('')}</tr>${rows.map((r) => `<tr>${r.map((c) => `<td style="border-bottom:1px solid #e4e7eb;padding:6px;vertical-align:top">${c}</td>`).join('')}</tr>`).join('')}</table>`;
const r = $('Report data').item.json;
const d = r.data;
const summary = $json.candidates?.[0]?.content?.parts?.map((p) => p.text).join('').trim() || null;
const n = (v) => (v === null || v === undefined ? '-' : Number(v).toLocaleString('en-US'));
const delta = (now, before) => n(now) + (now != null && before != null ? ` (${now - before >= 0 ? '+' : ''}${now - before})` : '');
const parts = [`<p style="color:#52606d;margin-top:0">${esc(d.week_start)} to ${esc(d.week_end)}</p>`];
if (summary) parts.push(`<p style="background:#f0f4f8;padding:12px;border-radius:6px">${esc(summary)}</p>`);
parts.push('<h3>Followers</h3>', table(['Platform', 'Followers'], [
  ['Facebook', delta(d.followers.facebook, d.prev_followers?.facebook)],
  ['Instagram', delta(d.followers.instagram, d.prev_followers?.instagram)],
]));
parts.push(`<h3>Posts this week (${d.posts.length})</h3>`);
parts.push(d.posts.length ? table(['Post', 'Reach', 'Views', 'Likes', 'Comments', 'Shares', 'Saves'], d.posts.map((p) => [
  `${p.permalink ? `<a href="${esc(p.permalink)}">${esc(p.id)}</a>` : esc(p.id)}<br><span style="color:#7b8794">${esc(p.platform)} · ${esc(p.type)}</span>`,
  n(p.reach), n(p.views), n(p.likes), n(p.comments), n(p.shares), n(p.saves),
])) : '<p>No posts went out this week.</p>');
if (d.failed.length) parts.push('<h3>Failed this week</h3>', table(['Post', 'Error'], d.failed.map((f) => [`${esc(f.id)}<br>${esc(f.platform)}`, esc(f.error)])));
return {
  client_id: r.client_id, week_start: d.week_start, data: d, summary,
  to: r.report_email, subject: `${d.client}: weekly social report, ${d.week_start} to ${d.week_end}`,
  html: layout(`Weekly report: ${d.client}`, parts.join('')),
};

